import type { Scenario, Scene } from '../types';
import { largeAdventure, largeEnd, largeScene, largeTags } from './largeContentTools';

type EvidenceStory = {
  id: string; title: string; subtitle: string; setting: string; risk: 'LOW' | 'MODERATE' | 'HIGH';
  claim: string; scene: string; inspect: [string, string, string];
  testTitle: string; test: string; actions: [string, string, string];
  interpretation: string; careful: string; accuse: string; lesson: string;
  reward?: { item: string; name: string; provenance: string; source: string };
  coins: number; combat?: boolean;
};

const stories: EvidenceStory[] = [
  { id:'the-scrape-beneath-the-lock', title:'The Scrape Beneath the Lock', subtitle:'A warehouse lock is damaged, but the marks do not yet say who opened it.', setting:'river warehouse', risk:'MODERATE', claim:'The night clerk says a thief forced the door.', scene:'A narrow bright scrape crosses the lower hasp, while the door frame has no fresh split. The warehouse owner points to the clerk; the clerk points to a cart crew that left at dusk.', inspect:['Compare the hasp with the spare key kept by the owner','Use your Pocket Toolkit to inspect the hinge pins without removing them','Ask the cart crew which side of the door they loaded from'], testTitle:'A Lock Can Be Opened More Than One Way', test:'The key turns stiffly and leaves a shallow line on the inside lip. The scrape is on the outside. This suggests separate contact, not a complete account of who entered.', actions:['Ask the owner to produce the key ledger','Keep the door closed and record the marks for the insurer','Question the clerk about the order of the night rounds'], interpretation:'The hasp was touched from outside, but the scrape alone does not identify a person or prove entry.', careful:'You preserve the hardware and record both accounts without naming a culprit.', accuse:'The clerk denies it; the owner suspends his pay, but the surviving marks cannot support your accusation.', lesson:'A fresh tool mark shows contact and direction only when compared with undisturbed surfaces; it does not identify a hand.', coins:2, combat:true },
  { id:'the-two-widths-at-morrow-road', title:'The Two Widths at Morrow Road', subtitle:'Two wagon widths appear in soft ground beside a missing crate.', setting:'rural road and loading yard', risk:'LOW', claim:'A teamster says one wagon carried the crate away.', scene:'Rain has softened the yard. Two wheel tracks leave the loading shed: one broad pair toward the public road, one narrow pair toward the stable. The crate’s seal is still on the floor.', inspect:['Measure the wheel spacing with a Survey Chain','Compare the tracks with the farm wagon standing by the stable','Ask the teamster to point out exactly when the crate was last seen'], testTitle:'The Yard Has More Than One Story', test:'The broad track matches the public wagon, but the narrow track begins beside the shed door. Neither track alone proves which load carried the crate.', actions:['Follow the broad track only to the road fork','Check the stable tally before questioning the teamster','Ask the yard owner to inventory the shed before anyone leaves'], interpretation:'A wagon left by the road and another moved near the shed; the missing crate remains unaccounted for.', careful:'The owner finds the crate behind a feed partition where it was staged for a different delivery.', accuse:'The teamster refuses the accusation; the track width is not a cargo manifest, and the yard delays his pay pending a recount.', lesson:'Wheel spacing can compare vehicles, but a track does not tell you what was on the wagon.', coins:1 },
  { id:'the-seal-with-the-second-notch', title:'The Seal with the Second Notch', subtitle:'A freight seal looks familiar until a clerk notices a small difference.', setting:'rail freight platform', risk:'MODERATE', claim:'A receiver says the crate was opened in transit.', scene:'The iron seal is intact, though its lower edge bears two notches. The signed waybill sketch shows one. The crate’s boards have no pry damage, and the receiver has not opened it.', inspect:['Use an Assayer’s Loupe to compare both notches','Ask the clerk to find the duplicate waybill before breaking the seal','Measure the crate’s outside dimensions against its listed packing'], testTitle:'A Mark Is Not a Name', test:'The second notch is older and rounded, not freshly cut. The sketch may be wrong, or the crate may have been resealed earlier; the evidence does not establish when.', actions:['Hold the crate for the sender’s written confirmation','Ask the receiver to accept it under a witnessed exception','Record the discrepancy and leave the sealed crate unopened'], interpretation:'There is a mismatch between the sketch and seal, but no proof of theft or tampering during this trip.', careful:'The clerk logs the exception and the receiver accepts responsibility without opening the freight.', accuse:'The receiver disputes your claim and the delivery is held; the age of the notch weakens an accusation of recent tampering.', lesson:'Rounded wear suggests age, but only a dated comparison can place a mark in a specific journey.', reward:{item:'waxImpressionKit',name:'Wax Impression Kit',provenance:'The rail clerk transfers his personally owned spare seal-impression kit after the discrepancy is documented; the active freight seals remain with the railway.',source:'seal comparison and accurate recordkeeping'}, coins:2 },
  { id:'the-ash-line-at-cooper-shed', title:'The Ash Line at Cooper Shed', subtitle:'A shed fire began near a stove, though the owner says it started outside.', setting:'farm supply shed', risk:'HIGH', claim:'The owner says a passerby set the shed alight.', scene:'The burned boards are wet from the bucket line. Ash is heaviest beneath a stove leg, while the outer door is scorched on its inside face. A worker says the stove was cold before supper.', inspect:['Compare the stove’s ash with the unburned hearth sweepings','Ask the worker when the stove was last tended','Mark the burn edge before the boards are moved'], testTitle:'Fire Leaves a Boundary, Not a Motive', test:'The deepest charring begins at the stove corner. A draft could have carried sparks outward; the door damage happened after the fire was inside.', actions:['Tell the owner the origin remains uncertain and preserve the boards','Ask the worker to demonstrate the stove’s damper setting','Accuse the passerby based on the owner’s account'], interpretation:'The fire likely spread from the stove area, but the available pattern cannot establish who lit it or whether it was deliberate.', careful:'The owner has the stove inspected before using the shed again and withdraws the unsupported accusation.', accuse:'The passerby is questioned and denies being near the shed; no physical evidence places them there.', lesson:'Burn depth can help locate where a fire grew hottest, but it does not establish intent or identity.', coins:2 },
  { id:'the-gate-pin-at-south-pasture', title:'The Gate Pin at South Pasture', subtitle:'A livestock gate fell open; the bent pin may show wear rather than sabotage.', setting:'farm pasture boundary', risk:'MODERATE', claim:'The farmer believes a neighbor pulled the pin to let cattle through.', scene:'The iron pin lies in grass beyond the hinge. One side is polished smooth; the other has a newer bright bend. Cattle prints cross the gap in both directions.', inspect:['Compare the pin against the hinge socket before straightening it','Use Field Calipers to compare the bright bend with the old wear','Ask the neighbor when they last used the shared lane'], testTitle:'Repeated Wear and One Fresh Bend', test:'The old polished side fits the socket. The new bend would let the pin ride upward if the gate struck the ground, but it could also follow rough handling.', actions:['Repair the hinge and watch the gate through one cattle turn','Ask both farms to agree on a temporary gate check','Accuse the neighbor of removing the pin'], interpretation:'The hinge has a plausible mechanical failure mode; the prints show cattle crossed, not who opened the gate.', careful:'The farms agree to repair the sagging post and share a gate check until the new pin is fitted.', accuse:'The neighbor disputes the accusation and points to the sagging post; the cattle tracks do not settle the disagreement.', lesson:'A bent fastener and worn socket can explain a gate failure without proving deliberate interference.', coins:1 },
  { id:'the-ledger-page-that-dried', title:'The Ledger Page That Dried', subtitle:'A damp ledger page has a missing line, but the ink may have run rather than been erased.', setting:'inn office', risk:'LOW', claim:'The innkeeper says a guest removed a payment entry.', scene:'The page is buckled from water. One line is pale, but its ink feathers into the paper fibers; the binding is intact and the next page carries a faint impression.', inspect:['Slip the page into a Waterproof Ledger Tube after it dries','Compare the next page’s pressure marks without tearing it free','Ask the clerk who carried the ledger during the leak'], testTitle:'A Faint Impression', test:'The next sheet preserves part of the line: a room number and two coin marks, but no name. It shows an entry existed, not who wrote or removed it.', actions:['Copy the surviving marks and leave the original in the inn’s custody','Ask the two guests in that room to compare their receipts','Tell the innkeeper the page proves one guest cheated'], interpretation:'A payment was likely recorded, but the surviving impression cannot identify the payer.', careful:'The clerk records the incomplete entry and checks the day receipts before settling the dispute.', accuse:'The guest denies it; the partial impression cannot support a named accusation.', lesson:'Pressure marks can preserve a line after ink fades, but they may omit the detail needed to identify a person.', reward:{item:'charcoalRubbingKit',name:'Charcoal Rubbing Kit',provenance:'The inn’s retired recorder gives you a duplicate rubbing kit from his own desk after you preserve the ledger without removing its page.',source:'careful document handling'}, coins:1 },
  { id:'the-rope-fibers-on-the-ferry-cleat', title:'The Rope Fibers on the Ferry Cleat', subtitle:'A mooring line parted overnight, and the ferryman suspects it was cut.', setting:'small ferry landing', risk:'MODERATE', claim:'The ferryman says someone cut the line to delay a freight crossing.', scene:'A short bundle of fibers remains on the cleat. Most ends are frayed and pale; a few are dark with river grit. The boat is tied safely to a second line and the landing is closed.', inspect:['Compare the break with the spare line’s fibers','Use Heavy Leather Gloves to turn the wet splice without pulling it','Ask who last secured the ferry and at what water level'], testTitle:'A Splice Under Strain', test:'The inner strands are stretched and fuzzy; the dark outer fibers may have been abraded against the cleat. A knife cut remains possible but is not visible across the bundle.', actions:['Replace the line and keep the broken end for the owner','Reopen only after the ferryman tests the second line with an empty boat','Accuse the last deckhand of cutting the rope'], interpretation:'The line failed under strain or abrasion; there is no clean cut establishing sabotage.', careful:'The ferry stays closed until the replacement line is tested, and the old end is retained for inspection.', accuse:'The deckhand says the old splice was already worn; no evidence supports a charge against them.', lesson:'A rope failure should be judged across the full bundle and splice; one damaged outer strand does not prove a cut.', coins:2 },
  { id:'the-switch-that-faced-east', title:'The Switch That Faced East', subtitle:'A rail switch was left in an unexpected position before the morning freight.', setting:'rail siding', risk:'HIGH', claim:'A foreman says a brakeman deliberately mis-set the switch.', scene:'The lever points toward the east siding, but the locking pin is not seated. Fresh gravel lies under the lever shoe. The freight is stopped at the signal; no train is moving through the junction.', inspect:['Compare the lever position with the chalked standard mark','Ask the night watch which crew last used the siding','Use your Pocket Toolkit to inspect the exposed locking pin'], testTitle:'A Lever Moved, a Cause Unknown', test:'The pin is bent at its exposed end and the gravel is scuffed. A wheel or a boot could have struck it; the position alone does not show who moved it.', actions:['Keep the signal at stop and call the railway fitter','Record both switch positions before the crew resets it','Accuse the brakeman before the day crew arrives'], interpretation:'The switch was not securely locked and may have been struck; the evidence does not identify a person.', careful:'The freight remains stopped while the fitter replaces the pin and the night crew gives separate accounts.', accuse:'The brakeman denies touching it; the loose pin makes the accusation premature.', lesson:'A mis-set switch proves a hazard, not sabotage; secure the route first and determine cause afterward.', coins:2, combat:true },
  { id:'the-stone-under-the-floorboard', title:'The Stone under the Floorboard', subtitle:'A hollow sound beneath an old office may mark a repair cavity, not a hidden passage.', setting:'abandoned toll office', risk:'MODERATE', claim:'A caretaker says someone entered through a concealed space.', scene:'One floorboard sounds hollow. Dust gathers along the wall, and the door’s rusted latch has not been disturbed. The caretaker heard footsteps below, but no cellar is shown on the plan.', inspect:['Use the Collapsible Sounding Rod to compare boards from firm ground','Look beneath the sill with your Folding Card Mirror','Compare the room outline with the old toll plan'], testTitle:'A Gap Beneath the Boards', test:'The rod finds a narrow void under the sill, too shallow for a person. A drain channel runs toward the road ditch; a loose board can explain the sound.', actions:['Lift only the loose board with the caretaker watching','Mark the drain route and ask a mason to inspect it','Tell the caretaker there is a secret tunnel'], interpretation:'A shallow drain or repair space explains the void; it does not establish that anyone entered beneath the room.', careful:'The caretaker closes the board and records the drain for a daylight repair.', accuse:'No tunnel is found. The caretaker withdraws the claim and asks the mason to check the drain before reopening the office.', lesson:'A probe can establish a void’s size and direction; it cannot turn a gap into a passable route.', coins:1 },
  { id:'the-missing-shears-at-the-mill', title:'The Missing Shears at the Mill', subtitle:'A missing pair of shears may have been borrowed, misplaced, or carried with the feed sacks.', setting:'mill loading floor', risk:'LOW', claim:'The miller says a new hand stole the shears.', scene:'A clean rectangle marks the dusty shelf. Fine chaff covers the floor toward the loading door, and the miller recalls using the shears to cut sack twine that morning.', inspect:['Check the tool list before searching the workers’ bags','Follow the chaff trail only to the public loading floor','Ask the carrier whether any cut twine was found in the wagon'], testTitle:'The Shears Were Used on a Sack', test:'A loose thread from the mill’s sack twine is caught beneath a weighing bench. The shears may have been set there, but the thread cannot show who moved them.', actions:['Look beneath the bench with the miller present','Ask the workers to check their own tool rolls voluntarily','Accuse the newest hand and demand a search'], interpretation:'The thread links the shears to sack work; it does not identify who used them or whether they left the mill.', careful:'The shears turn up under the bench, where the miller had set them before the rush.', accuse:'The new hand refuses a search and leaves; the miller later finds the shears beneath the bench.', lesson:'A material trace can connect an object to a task without identifying the person who handled it.', coins:1 },
  { id:'the-boot-mark-in-the-ash', title:'The Boot Mark in the Ash', subtitle:'A print appears near a cold stove after a storeroom fire.', setting:'town storeroom', risk:'MODERATE', claim:'The shopkeeper says the night porter started the fire.', scene:'A single boot mark crosses gray ash to the stove. The soles of three workers share a common hobnail pattern; the ash is disturbed by the bucket line.', inspect:['Measure the print length with a folding rule','Ask each worker when they last crossed the room','Compare the print to the porter’s boot without making him remove it'], testTitle:'Three Similar Soles', test:'The print is close to the porter’s size, but two other workers wear the same maker’s pattern. Water has softened the edges and changed the length.', actions:['Record the print and keep all three workers’ accounts','Ask the porter to explain the stove schedule','Accuse the porter based on the size match'], interpretation:'The print is compatible with several workers and does not identify its maker.', careful:'The shopkeeper checks the stove and finds a cracked ash pan that spilled embers before closing.', accuse:'The porter denies it; the print cannot distinguish his boots from the others.', lesson:'A size and tread match narrows possibilities but is not individual identification.', coins:2 },
  { id:'the-two-seals-at-blackwater-dock', title:'The Two Seals at Blackwater Dock', subtitle:'A wet crate carries one shipping mark and a ledger records another.', setting:'river dock storehouse', risk:'MODERATE', claim:'The dock clerk says a crate was swapped during unloading.', scene:'A dry wax seal says “North Wharf”; the damp ledger records “Bell Landing.” The crate is still on the dock and has not been opened. A rope scuff crosses one corner.', inspect:['Compare the seal impression with the clerk’s copybook','Use the Waterproof Ledger Tube to protect the wet entry','Ask the boat crew which landing they left and where the crate came aboard'], testTitle:'A Route Discrepancy', test:'The crew names Bell Landing, while the crate’s outer seal was reused from an earlier shipment. The scuff may come from transfer between boats.', actions:['Hold the crate for both owners to verify the marks','Have the clerk correct the ledger with a witnessed note','Accuse the boat crew of switching cargo'], interpretation:'The recorded route and outer seal conflict; neither proves what the crate contains or who changed its label.', careful:'Both owners agree to hold the unopened crate until their loading tallies are compared.', accuse:'The boat crew disputes the accusation; the transfer scuff is consistent with ordinary unloading.', lesson:'A cargo mark can outlast the shipment it first identified; compare it with the current ledger and witnesses.', coins:2 },
  { id:'the-stone-chips-at-the-quarry', title:'The Stone Chips at the Quarry', subtitle:'A cracked marker stone may have been struck by a cart or weakened by weather.', setting:'quarry lane', risk:'MODERATE', claim:'The foreman says a teamster damaged the boundary marker.', scene:'Fresh pale chips lie on the uphill side. The crack follows an older dark seam through the stone, and cart ruts pass within a handspan of the marker.', inspect:['Use Field Calipers to compare the crack opening top and bottom','Measure the cart rut distance from the marker with Survey Chain','Ask the teamster to show the route taken with the empty cart'], testTitle:'A Crack That Was Already There', test:'The dark seam continues beneath the fresh chips. A cart could have knocked loose the face, but the stone was weakened before the impact.', actions:['Set a barrier and ask a mason to assess the marker','Record the cart’s route and repair the warning board','Charge the teamster for the whole break'], interpretation:'The cart may have worsened old damage; the evidence does not support assigning all responsibility to its driver.', careful:'The foreman shares the repair cost with the quarry owner and moves carts away until the stone is secured.', accuse:'The teamster refuses full payment, and the foreman accepts that the old seam complicates blame.', lesson:'Fresh fragments show a recent change, while a darker seam can show older weakness; both may matter.', coins:1 },
  { id:'the-empty-hook-in-the-tool-room', title:'The Empty Hook in the Tool Room', subtitle:'A tool is missing from a wall, but the inventory was copied before the last shift.', setting:'bridge crew tool room', risk:'LOW', claim:'The crew chief says a visiting worker took the hammer.', scene:'A clean outline remains on the peg board. The chalk inventory is dated yesterday, before the visiting worker arrived; today’s shift sheet has a torn corner.', inspect:['Compare the last signed inventory with the peg board','Ask the storekeeper who issued tools at dawn','Check the repair bench for an item moved off its hook'], testTitle:'The Inventory Is Older Than the Visit', test:'A hammer was signed out to the bridge crew before the visitor came. The torn shift sheet hides the return mark, not necessarily a theft.', actions:['Search the repair bench with the storekeeper','Ask the visitor to wait while the crew checks its own issue book','Accuse the visitor and report the tool stolen'], interpretation:'The tool was issued to the crew; the missing return mark leaves its current location unknown.', careful:'The hammer is found beneath the repair bench beside a brace being fitted.', accuse:'The visitor leaves offended; the crew later finds its hammer beneath the bench.', lesson:'A missing item and a missing record are different problems; establish the inventory’s date before tracing possession.', coins:1 },
  { id:'the-chalk-line-at-the-old-boundary', title:'The Chalk Line at the Old Boundary', subtitle:'A survey mark appears to cross a property line after recent rain.', setting:'farm and county boundary', risk:'MODERATE', claim:'One neighbor says the other moved the boundary marker.', scene:'A white chalk line joins a stone marker to a fence post. Rain has washed the center away, but both ends remain. The county map uses an older creek bend as its reference.', inspect:['Compare the line with the county map’s fixed road crossing','Measure from the stone to the fence post with Survey Chain','Ask each neighbor who last renewed the marker'], testTitle:'The Line Was a Temporary Work Mark', test:'The chalk begins at a newer fence repair, not at the county stone. It could mark a planned brace rather than a land claim.', actions:['Have both neighbors witness a fresh measurement from the road crossing','Ask the county clerk to bring the original survey note','Accuse the neighbor who benefits from the shifted fence'], interpretation:'The chalk line records recent work; it is not a surveyed property boundary.', careful:'The neighbors agree to leave the fence in place until the clerk checks the original survey.', accuse:'The accused neighbor refuses further discussion; the chalk does not establish where the legal line lies.', lesson:'A visible mark is not authoritative merely because it is straight; identify who made it and what reference it uses.', coins:2 },
  { id:'the-glass-in-the-lantern-room', title:'The Glass in the Lantern Room', subtitle:'A signal lens is cracked, and the keeper suspects a visitor touched it.', setting:'coastal signal station', risk:'LOW', claim:'The keeper says a visitor broke the lens after closing.', scene:'The crack begins at a small chip on the inner rim. Dust on the outer guard is undisturbed; the lens frame is loose at one screw.', inspect:['Use your Folding Card Mirror to view the inner rim','Ask when the frame was last tightened','Compare the broken edge with a small retained fragment'], testTitle:'A Loose Frame', test:'The screw is short by one turn and the rim presses against the glass. A bump may have finished the crack, but the lens was under strain already.', actions:['Keep the station closed until the glazier checks the frame','Record the visitor’s account alongside the loose screw','Demand that the visitor pay for the whole lens'], interpretation:'The frame likely contributed to the break; the evidence cannot tell whether the visitor also struck it.', careful:'The keeper withdraws the full charge and orders a sound frame before reopening the signal.', accuse:'The visitor denies striking it, and the keeper cannot prove the glass was sound before their visit.', lesson:'A fracture can begin at a stressed fitting; the nearest person is not automatically the cause.', coins:1 },
  { id:'the-dry-footprints-in-wet-clay', title:'The Dry Footprints in Wet Clay', subtitle:'A trail of dry prints crosses a damp cellar floor after a locked-room complaint.', setting:'inn cellar', risk:'MODERATE', claim:'The landlord says a guest crossed the cellar after it was locked.', scene:'Most of the floor is damp from a leaking cask. A line of dry-edged prints passes from the stair to a coal alcove; the cellar door seal is intact.', inspect:['Check whether the prints cross the wettest patch','Look for a second exit on the old cellar plan','Ask the cook who carried coal before the door was sealed'], testTitle:'A Track Can Be Older Than the Water', test:'The prints sit beneath a fresh drip trail. They likely predate the leak and the seal, though the floor cannot show how long before.', actions:['Show the landlord the overlapping drip marks','Ask the cook to account for the coal delivery','Accuse the guest using the print trail'], interpretation:'The prints are older than the current leak and do not establish a crossing after the cellar was locked.', careful:'The landlord checks the delivery schedule and finds the cook’s earlier coal run on the day sheet.', accuse:'The guest denies returning; the overlapping water marks contradict the timing in the accusation.', lesson:'When two traces overlap, their order can be clearer than their source; sequence is not identity.', coins:1 },
  { id:'the-bent-pin-in-the-harvest-engine', title:'The Bent Pin in the Harvest Engine', subtitle:'A jammed machine stopped suddenly, and the owner suspects the hired mechanic.', setting:'threshing machine yard', risk:'HIGH', claim:'The owner says the mechanic bent the pin by forcing the drive.', scene:'The drive is stopped and the belt is slack. One pin is bent toward the wheel; a fresh scrape appears on the guard, and the mechanic says the machine shuddered before he touched it.', inspect:['Use Field Calipers to compare the pin with an unused spare','Ask the mechanic to show where the belt first slipped','Check the guard bolts before anyone turns the wheel'], testTitle:'A Jam Before the Repair', test:'The guard bolt is loose and the belt edge is frayed. Either could have caught the pin; the machine must remain still until repaired.', actions:['Keep the engine stopped and let the owner and mechanic inspect together','Replace the pin only after the guard is secured','Accuse the mechanic of forcing the drive'], interpretation:'The loose guard offers a plausible cause of the jam; the bent pin does not show who caused it.', careful:'The guard is secured and the pin replaced; the owner pays the mechanic for the repair time.', accuse:'The mechanic leaves the job; a second fitter finds the guard bolt loose and cannot support the accusation.', lesson:'A damaged part may be a consequence of a jam rather than its cause; inspect connected components before blaming the last hand.', coins:2 },
  { id:'the-map-with-two-norths', title:'The Map with Two Norths', subtitle:'A route copy points toward a washed-out road, but its margin shows a second north mark.', setting:'county survey office', risk:'LOW', claim:'The clerk says the surveyor delivered a defective map.', scene:'The map has a compass rose in the corner and a smaller arrow near the river. The road names are correct, but the copied scale differs from the ledger.', inspect:['Compare the map to the Survey Chain distances in the field notes','Ask the clerk when the smaller arrow was added','Protect the sheet in a Lockable Map Case before taking it outside'], testTitle:'A Copy for a Different Purpose', test:'The smaller arrow aligns with the map’s folded orientation, not true north. The scale discrepancy comes from a reduced copy.', actions:['Mark the copy “not for measurement” and return it to the clerk','Ask the surveyor to confirm which north the route notes use','Accuse the surveyor of falsifying the route'], interpretation:'The map was reduced and rotated for filing; its road sketch remains useful, but distances should not be measured from it.', careful:'The clerk labels the copy and requests a corrected scale rather than blaming the surveyor.', accuse:'The surveyor shows the full field notes; the mismatch is a filing copy error, not falsification.', lesson:'A map can preserve direction while losing scale; check its purpose and orientation before relying on measurements.', coins:1 },
  { id:'the-wax-on-the-keyhole', title:'The Wax on the Keyhole', subtitle:'A thin wax smear appears on a locked cabinet, but the cabinet was used that morning.', setting:'town recorder’s office', risk:'LOW', claim:'The recorder says someone copied the cabinet key.', scene:'A small wax fleck clings below the keyhole. The cabinet has a fresh key scratch and a smear of lamp oil on its handle; the recorder says only staff entered.', inspect:['Compare the wax with the office seal wax','Ask which staff used the cabinet before noon','Look at the key’s worn teeth without trying it in the lock'], testTitle:'One Fleck, Several Explanations', test:'The wax matches the recorder’s seal stick. It could have transferred from a document packet; the scratch is consistent with the usual key.', actions:['Ask the recorder to inventory the cabinet contents with a witness','Keep the cabinet locked and note the seal wax source','Accuse the clerk who had the morning key'], interpretation:'The wax has an ordinary source and the key wear is not new; no evidence shows a copied key.', careful:'The inventory is complete and the recorder adds a cloth divider between seal supplies and keys.', accuse:'The clerk denies copying anything; the recorder finds no missing contents and withdraws the claim.', lesson:'A material match can show a shared source without showing when or how it reached a surface.', coins:1 },
  { id:'the-quiet-bell-at-milepost-four', title:'The Quiet Bell at Milepost Four', subtitle:'A signal bell did not ring during a wagon passage, though no one admits touching it.', setting:'toll road milepost', risk:'MODERATE', claim:'The toll keeper says the passing team ignored the warning bell.', scene:'The bell rope is slack and its knot is damp. A cart passed before dawn; fresh mud covers the threshold but the bell clapper has no new mark.', inspect:['Test the rope from the safe side of the post','Ask the teamster what signal was visible in fog','Look for a second bell pull at the road-facing window'], testTitle:'A Signal Could Not Carry', test:'The rope has slipped through its worn eye, so pulling from the keeper’s side may not move the clapper. The team may not have heard anything.', actions:['Repair the eye and test the bell with the keeper','Post a daylight flag until the rope is replaced','Charge the teamster for ignoring a signal'], interpretation:'The bell mechanism was unreliable; the evidence does not show that the driver heard or ignored a warning.', careful:'The keeper posts a visible flag and delays night traffic until the rope eye is replaced.', accuse:'The teamster says no signal sounded; the failed rope supports that account.', lesson:'A missing response does not prove someone ignored a signal; first test whether the signal could be made.', coins:1 },
  { id:'the-notches-on-the-old-millstone', title:'The Notches on the Old Millstone', subtitle:'A carved mark may be a maker’s sign or a later tally.', setting:'abandoned mill foundation', risk:'LOW', claim:'A local collector says the stone belonged to a famous millwright.', scene:'Three shallow notches sit under a layer of limewash. A newer date is scratched across the rim, and the stone rests in a foundation built decades after the claimed millwright died.', inspect:['Use the Assayer’s Loupe to compare the cuts beneath the lime','Make a charcoal rubbing without lifting the stone','Ask the local mason when the foundation was built'], testTitle:'A Mark Out of Place', test:'The notches are older than the date scratch, but the foundation reused stone from elsewhere. The maker’s identity is not established.', actions:['Record the marks and leave the stone in place','Ask the collector for the source of the attribution','Call the notches proof of the famous maker'], interpretation:'The stone was reused and bears at least two periods of marking; its original workshop remains unknown.', careful:'The collector agrees to describe the attribution as a local tradition, not a verified ownership record.', accuse:'The collector produces an old account naming the millwright, but the stone’s reuse means the marks alone cannot confirm it.', lesson:'A reused object can carry marks from different times; sequence and provenance are separate questions.', coins:1 },
  { id:'the-red-thread-at-the-bridge', title:'The Red Thread at the Bridge', subtitle:'A red thread caught on a brace may be a marker, a repair remnant, or a warning.', setting:'county bridge', risk:'MODERATE', claim:'The inspector says a worker tied the thread to hide a cracked brace.', scene:'A red thread is knotted around the downstream brace. The wood is sound at the knot but hairline-split at the upper bolt. The work crew uses red thread to mark tools awaiting return.', inspect:['Use your Folding Card Mirror to see the back of the brace','Compare the split with the bolt’s washer pressure','Ask the crew what their red-thread marks mean'], testTitle:'The Mark and the Crack', test:'The thread is a tool-return marker, not a crack marker. The split follows the bolt grain and may be old; the bridge remains closed pending a full check.', actions:['Tell the inspector the mark is not evidence of concealment','Keep the bridge closed and ask the crew to inspect the bolt','Accuse the worker who tied the thread'], interpretation:'The thread has an ordinary crew meaning; the crack still requires inspection, but does not prove anyone hid it.', careful:'The inspector thanks you for separating the unrelated marker from the structural concern.', accuse:'The worker says they marked a wrench; the inspector withdraws the claim but keeps the bridge closed.', lesson:'A suspicious-looking mark must be interpreted in its working context before it becomes evidence.', coins:2 },
  { id:'the-sealed-letter-at-cedar-post', title:'The Sealed Letter at Cedar Post', subtitle:'A courier’s delivery receipt is signed, but the recipient says no letter arrived.', setting:'stage post office', risk:'LOW', claim:'The postmaster says the courier lost the letter after signing.', scene:'The receipt bears a clear mark, but the wax seal on the returned wrapper is unbroken. The postmaster’s book shows the recipient was away that day; no one has opened the letter.', inspect:['Compare the receipt mark with the postmaster’s witness book','Ask the courier where the wrapper was returned','Keep the letter sealed while checking the route ledger'], testTitle:'Custody Is Not Delivery', test:'The signature belongs to the recipient’s household, but not necessarily the recipient. The intact wrapper suggests the letter came back unopened.', actions:['Leave the letter sealed and ask the household who signed','Record the custody gap for the sender','Accuse the courier of keeping the contents'], interpretation:'The letter was accepted by someone at the household and later returned unopened; its contents remain unknown.', careful:'The sender is notified of the return and the letter stays sealed for a new delivery attempt.', accuse:'The courier denies opening it, and the intact seal supports that the contents remain private.', lesson:'A signed receipt records custody at one moment; it does not establish that the named person read a document.', reward:{item:'waterproofLedgerTube',name:'Waterproof Ledger Tube',provenance:'The postmaster transfers a separately owned spare tube after the sealed letter is logged for redelivery; the original remains closed.',source:'preserving a sealed document and an accurate custody record'}, coins:1 },
  { id:'the-worn-notch-on-the-spade', title:'The Worn Notch on the Spade', subtitle:'A borrowed tool returned with a new notch is blamed on the last user.', setting:'rail work camp', risk:'MODERATE', claim:'The foreman says a worker damaged a shared spade.', scene:'The notch is bright, but the handle is polished smooth where it has rubbed against a wagon rack. A second spade has the same bright mark on its blade.', inspect:['Compare both spades under an Assayer’s Loupe','Ask the tool clerk how the spades are carried','Use a folding rule to compare the notch depth without filing it'], testTitle:'Two Tools, One Rack', test:'The rack has a bent iron lip at exactly the blade height. Both spades may have struck it while stowed; the mark is not unique to the last user.', actions:['Pad the rack and record the shared damage','Ask the crew to identify who last sharpened each blade','Charge the last borrower for the notch'], interpretation:'The storage rack can explain both notches; no individual worker is identified.', careful:'The foreman changes the rack and withdraws the damage charge.', accuse:'The worker disputes the charge, and the second matching notch makes responsibility uncertain.', lesson:'Repeated matching damage often points to a shared process or storage point rather than one person.', coins:1 },
  { id:'the-wagon-shadow-at-the-inn', title:'The Wagon Shadow at the Inn', subtitle:'A witness saw a wagon leave after midnight, but the moon made direction uncertain.', setting:'inn yard and lane', risk:'MODERATE', claim:'The innkeeper says a guest took a wagon from the yard.', scene:'The gate latch is closed. A lantern shadow fell across the wall, and a witness remembers a wagon moving left; the yard has two exits on opposite sides.', inspect:['Ask the witness to stand where they watched','Compare the wheel ruts at both gates','Use Field Glasses at dawn to inspect the far lane markers'], testTitle:'Left from Which Side?', test:'From inside the room, “left” points toward the stable gate; from the porch, it points toward the road gate. The witness did not see the wagon’s face.', actions:['Walk both gates with the witness and record the view','Ask the stablehand whether the yard wagon was moved for cleaning','Accuse the guest who rented the near room'], interpretation:'A wagon moved or cast a moving shadow, but the witness’s direction is ambiguous and the gate latch is undisturbed.', careful:'The stablehand confirms the yard wagon was shifted before closing and returned from the stable gate.', accuse:'The guest denies moving it; the witness cannot identify the wagon or its driver.', lesson:'A witness’s viewpoint can reverse a direction; establish where they stood before treating a description as a route.', coins:1 },
  { id:'the-stone-that-rang-twice', title:'The Stone That Rang Twice', subtitle:'A quarry stone gives two different sounds, and workers disagree whether it is cracked.', setting:'quarry face', risk:'HIGH', claim:'The quarry boss says a worker struck sound stone too hard.', scene:'A cut block hangs secured on its timber bed. One corner rings clear; the other gives a dull note. A dark vein crosses the face and a wedge is still seated.', inspect:['Tap only the supported face with the Bridgewright’s Hammer','Use the sounding rod on the ground below the block','Ask the cutter where the wedge was driven'], testTitle:'A Vein Is Not a Verdict', test:'The dull note follows the dark vein, which may be natural or a crack. The block stays supported; no one should stand beneath it until the mason checks.', actions:['Keep the exclusion line and call the mason','Compare the sound on another block from the same seam','Blame the cutter for striking the wrong face'], interpretation:'The stone’s sound differs along a vein, but the evidence does not establish whether the cutter caused a fracture.', careful:'The block is lowered under the mason’s direction and found usable only after trimming.', accuse:'The cutter says the vein was present before work; no witness saw the first strike.', lesson:'A change in sound can locate a difference inside stone, but only a supported inspection can determine its cause.', coins:2 },
  { id:'the-scratch-inside-the-cabinet', title:'The Scratch Inside the Cabinet', subtitle:'A locked cabinet has a fresh scratch on its inner face.', setting:'county clerk’s office', risk:'LOW', claim:'The clerk says a visitor forced the cabinet from outside.', scene:'The keyhole has no fresh marks. A narrow scratch crosses the inside edge of the door, and dust on the shelf is disturbed near a removable back panel.', inspect:['Use the Folding Card Mirror to view the panel seam','Ask who holds keys to the office','Check the cabinet inventory before moving papers'], testTitle:'The Mark Faces Inward', test:'The scratch begins behind the panel, which can be removed from inside the records closet. That suggests access from the adjoining room, but the panel is not locked.', actions:['Secure both rooms and ask the clerk to inventory the papers','Have a carpenter inspect the panel before accusing anyone','Accuse the visitor who came last'], interpretation:'The cabinet may have been reached from the closet; the scratch does not establish who used that access.', careful:'The clerk finds no missing papers and orders the back panel secured before the office reopens.', accuse:'The visitor denies it, and the unfastened panel offers an access path available to staff as well.', lesson:'The direction of damage can narrow an access route without identifying who used it.', coins:1 },
  { id:'the-print-below-the-window', title:'The Print Below the Window', subtitle:'A muddy print appears beneath a closed upstairs window.', setting:'boarding-house courtyard', risk:'MODERATE', claim:'The landlord says a boarder climbed in through the window.', scene:'One muddy boot print lies beneath the sill. The wall has no scuffing, but a rain barrel stands nearby and its lid is wet. The room’s occupant is away.', inspect:['Measure the gap from barrel rim to sill with a Survey Chain','Look for a matching print on the barrel lid','Ask the yard keeper when the barrel was last moved'], testTitle:'A Step, Not a Climb', test:'The print sits on the barrel’s outer rim, which was moved beneath the window for rain collection. No wall scuffs or disturbed latch are visible.', actions:['Leave the room closed and tell the landlord what the print supports','Ask the yard keeper to restore the barrel to its marked place','Accuse the absent boarder of climbing in'], interpretation:'Someone stepped near the window, likely while moving the barrel; there is no evidence the room was entered.', careful:'The landlord waits for the boarder and checks the room inventory with them present.', accuse:'The boarder returns angry; the print does not show a climb or entry.', lesson:'A trace near an opening is not proof that someone crossed it; look for evidence on both sides.', coins:1 },
  { id:'the-dented-buckle-on-the-pack', title:'The Dented Buckle on the Pack', subtitle:'A surveyor’s instrument case shifted on the trail and the guide blames a porter.', setting:'survey camp trailhead', risk:'MODERATE', claim:'The surveyor says the porter overloaded one side of the pack.', scene:'The buckle is bent outward; the strap is damp and stretched at one hole. The instrument case is intact, and the porter says the saddle slipped on a side slope.', inspect:['Use Field Calipers to compare the buckle with its opposite side','Ask the porter to show the slope and saddle position','Check the load list for the case’s weight and placement'], testTitle:'Uneven Load or Slipped Saddle?', test:'The saddle’s left pad is compressed and the strap stretch matches a sudden shift. The load may have been uneven too; one sign does not exclude the other.', actions:['Refit the saddle and walk the animal unloaded first','Repack the instrument low and centered','Charge the porter for the damaged buckle'], interpretation:'The saddle slipped and the load was high; responsibility may be shared between packing and terrain.', careful:'The team repairs the buckle and changes the packing order before continuing.', accuse:'The porter disputes the charge and points to the saddle pad; the surveyor agrees to review the packing list.', lesson:'A damaged fastening can result from load placement and movement together; inspect the whole system before assigning blame.', coins:2 },
  { id:'the-old-mark-at-wren-station', title:'The Old Mark at Wren Station', subtitle:'A symbol on a station wall is called a warning by one clerk and a mason’s mark by another.', setting:'closed railway station', risk:'LOW', claim:'The clerk says the symbol marks a concealed room.', scene:'A shallow triangle is cut into a foundation stone. Mortar covers one edge; a newer chalk arrow points toward the platform. The station plan shows no room behind the wall.', inspect:['Make a charcoal rubbing without scraping the stone','Compare the cut with marks on nearby foundation blocks','Ask the retired mason what symbols their crew used'], testTitle:'A Builder’s Reference Mark', test:'The retired mason recognizes a setting-out mark used to align foundation courses. The chalk arrow is recent and separate; no cavity is indicated.', actions:['Record both marks with their different dates','Ask the clerk to amend the station note','Call the triangle proof of a hidden room'], interpretation:'The carved sign is likely a construction mark; the later chalk arrow remains unexplained but does not establish a passage.', careful:'The clerk corrects the plan note and leaves the chalk arrow for the railway to inspect.', accuse:'The clerk withdraws the claim of a hidden room; the later arrow’s maker remains unknown.', lesson:'Similar marks can belong to different systems and periods; compare material, placement, and local practice.', coins:1 },
  { id:'the-copper-button-at-the-toll', title:'The Copper Button at the Toll', subtitle:'A button near a toll drawer tempts the keeper to name the last traveler.', setting:'roadside toll house', risk:'MODERATE', claim:'The keeper says the traveler who argued about the fee returned after dark.', scene:'A copper button lies beside the drawer. The latch is closed and a dusty window has no fresh prints; two regular carriers wear similar coats with matching buttons.', inspect:['Ask the two carriers whether either coat is missing a button','Compare the button’s back with the toll clerk’s sewing tin','Check the fee book for who entered before the drawer was closed'], testTitle:'A Common Button', test:'The button matches a local coat maker’s stock. The fee book records two visits and the drawer is short one coin, but no mark ties the button to either carrier.', actions:['Record the shortage and improve the drawer’s closing tally','Ask both carriers to return with their coat if they choose','Accuse the traveler who argued about the fee'], interpretation:'A coin is missing and a common button was dropped; the evidence does not connect the two.', careful:'The keeper changes the closing tally and discovers the missing coin in the drawer’s hinge recess.', accuse:'The traveler refuses the accusation; the coin is later found in the hinge recess.', lesson:'Two unexplained facts do not become a connection merely because they occur in the same room.', coins:1 },
  { id:'the-canvas-seam-at-the-caravan-yard', title:'The Canvas Seam at the Caravan Yard', subtitle:'A cargo cover was opened, though its cord remains tied.', setting:'caravan yard', risk:'MODERATE', claim:'The master says a porter inspected a sealed crate.', scene:'The cover cord is still knotted, but one seam has a fresh stitch in darker thread. The crate seal beneath it is unbroken. The porter says rain tore the canvas during the night.', inspect:['Use the Assayer’s Loupe to compare thread twist and wear','Ask who repaired the canvas and whether the crate was moved','Check the seal before lifting the cover'], testTitle:'A Repair Outside the Knot', test:'The dark stitch passes through an older tear and stops short of the knot. The repair may have been made from outside; the sealed crate was not opened.', actions:['Record the patch and leave the seal intact','Ask the porter to show the repaired canvas in daylight','Accuse the porter of opening the crate'], interpretation:'The cover was repaired, but the intact seal gives no evidence the crate was opened.', careful:'The master accepts the repair explanation and marks the cover for replacement after delivery.', accuse:'The porter denies opening anything; the sealed cargo supports their account, though not who stitched the canvas.', lesson:'A repaired outer cover can look newly altered while the protected cargo remains untouched.', coins:2 },
  { id:'the-rut-that-stopped-at-the-creek', title:'The Rut That Stopped at the Creek', subtitle:'A wagon track ends at a creek bank after a missing-person report.', setting:'creek crossing and orchard lane', risk:'MODERATE', claim:'A family says a traveler was carried away in a wagon.', scene:'A fresh rut runs to the creek and stops at the firm bank. Across the water, the stones are dry. A dropped glove lies upstream beside a footpath leading toward the orchard.', inspect:['Probe the near-bank mud with a Collapsible Sounding Rod','Follow the footpath only as far as the first orchard marker','Ask the family when they last saw the traveler wearing the glove'], testTitle:'No Track Across the Water', test:'The wagon did not cross at this bank; there are no matching ruts opposite. The glove is dry inside, so it may have been dropped before the morning dew.', actions:['Follow the marked footpath with a family member','Signal the orchard keeper and wait at the crossing','Tell the family the traveler was taken by wagon'], interpretation:'A wagon reached the bank, but no evidence shows it crossed or carried the missing person. The footpath remains a separate lead.', careful:'The orchard keeper finds the traveler resting in a shed after a sprained ankle; they had walked there before the wagon arrived.', accuse:'The family’s fear grows, but the crossing gives no support for an abduction claim.', lesson:'A track ending at water does not show what happened next; inspect both banks and keep separate trails separate.', coins:2 },
  { id:'the-stamp-on-the-receipt', title:'The Stamp on the Receipt', subtitle:'A merchant’s receipt has an official-looking stamp that the town clerk does not recognize.', setting:'market counting room', risk:'LOW', claim:'The merchant says the stamp proves the goods were inspected.', scene:'The red stamp bears the town initials, but the date is written in blue pencil and the clerk’s signature line is blank. A second receipt from the same day has no stamp.', inspect:['Compare the stamp with the town recorder’s public seal book','Ask the merchant which inspector witnessed the count','Protect both receipts in a Waterproof Ledger Tube'], testTitle:'A Seal Without a Witness', test:'The stamp impression resembles the town mark but is smaller and lacks its outer ring. The recorder’s book can confirm the design, not who applied it.', actions:['Ask the recorder to verify the seal before releasing payment','Hold the goods and record the discrepancy','Accuse the merchant of forging an official paper'], interpretation:'The stamp is inconsistent with the public seal; it may be a shop mark or an unauthorized copy, but authorship is unknown.', careful:'The buyer delays payment until the recorder checks the seal and the merchant produces the inspector’s name.', accuse:'The merchant denies forgery; no witness saw who stamped the receipt.', lesson:'A mark resembling an authority seal warrants verification, but resemblance alone does not identify its maker.', coins:1 },
  { id:'the-sound-behind-the-brick', title:'The Sound Behind the Brick', subtitle:'A repeated knock comes from a wall beside an old service passage.', setting:'closed inn service corridor', risk:'MODERATE', claim:'The innkeeper says a trespasser is trapped behind the wall.', scene:'The wall is solid brick except for a repaired patch near the floor. A knock repeats after a cart passes outside; dust falls from the mortar seam, and the old plan shows a drain beyond the wall.', inspect:['Use the Folding Card Mirror at the low air gap','Tap the wall from two marked points and compare the sound','Ask the innkeeper when the drain was last cleared'], testTitle:'A Vibration Through the Drain', test:'The sound travels through the old drain and follows passing carts. The repaired patch is dry and stable; no voice or movement answers from behind it.', actions:['Mark the patch for a mason and stop opening the wall','Check the drain outlet from the courtyard','Tell the innkeeper someone is trapped inside'], interpretation:'The sound has a plausible route through the drain; it does not establish a person behind the brick.', careful:'The innkeeper clears the drain from the courtyard and leaves the sound unexplained only until the next cart passes.', accuse:'No one is found behind the wall, and the innkeeper apologizes for alarming the staff.', lesson:'Repeated sound can travel through a connected space; locate a path before inferring a hidden person.', coins:1 },
];

const s = (id: string, title: string, text: string, choices: Scene['choices']) => largeScene(id, title, text, choices);
const e = (id: string, title: string, text: string) => largeEnd(id, title, text);
const gearGain = (item: string, provenance: string, flag: string) => ({ gainItems: [item], gainItemProvenance: { [item]: provenance }, historyFlags: [flag] });
const releasedSpare: Record<string, string> = {
  'the-scrape-beneath-the-lock':'pocketToolkit', 'the-two-widths-at-morrow-road':'surveyChain',
  'the-seal-with-the-second-notch':'waxImpressionKit', 'the-ash-line-at-cooper-shed':'heavyLeatherGloves',
  'the-gate-pin-at-south-pasture':'fieldCalipers', 'the-ledger-page-that-dried':'charcoalRubbingKit',
  'the-rope-fibers-on-the-ferry-cleat':'fieldCalipers', 'the-switch-that-faced-east':'telegraphLineTester',
  'the-stone-under-the-floorboard':'collapsibleSoundingRod', 'the-missing-shears-at-the-mill':'foldingCardMirror',
  'the-boot-mark-in-the-ash':'assayersLoupe', 'the-two-seals-at-blackwater-dock':'waterproofLedgerTube',
  'the-stone-chips-at-the-quarry':'carpenterSquare', 'the-empty-hook-in-the-tool-room':'foldingBenchClamp',
  'the-chalk-line-at-the-old-boundary':'joinersFoldingRule', 'the-glass-in-the-lantern-room':'lanternGuard',
  'the-dry-footprints-in-wet-clay':'brassPlumbBob', 'the-bent-pin-in-the-harvest-engine':'foremanMultiTool',
  'the-map-with-two-norths':'lockableMapCase', 'the-wax-on-the-keyhole':'foldingPryTool',
  'the-quiet-bell-at-milepost-four':'conductorWhistle', 'the-notches-on-the-old-millstone':'foldingTrailMarker',
  'the-red-thread-at-the-bridge':'joinersFoldingRule', 'the-sealed-letter-at-cedar-post':'waterproofLedgerTube',
};

function build(c: EvidenceStory): Scenario {
  const item = releasedSpare[c.id] ?? c.reward?.item;
  const itemName = item ? (c.reward?.item === item ? c.reward.name : item.replace(/([A-Z])/g, ' $1').replace(/^./, (letter) => letter.toUpperCase())) : undefined;
  const provenance = item ? (c.reward?.item === item ? c.reward.provenance : `The ${c.setting} custodian transfers a separately owned spare ${itemName} as compensation after your documented inspection; operational equipment remains with its owner.`) : undefined;
  const itemSource = item ? (c.reward?.item === item ? c.reward.source : 'recording a careful inspection and preserving the evidence') : undefined;
  const specialistUse: Record<string, { index: number; item: string; label: string }> = {
    'the-scrape-beneath-the-lock': { index:0, item:'waxImpressionKit', label:'Press a wax copy of the scrape before comparing the hasp' },
    'the-two-seals-at-blackwater-dock': { index:0, item:'waxImpressionKit', label:'Take a wax impression of the shipping seal for the ledger' },
    'the-wax-on-the-keyhole': { index:0, item:'waxImpressionKit', label:'Compare the keyhole fleck with an impression of the office seal' },
    'the-notches-on-the-old-millstone': { index:1, item:'charcoalRubbingKit', label:'Copy the raised notches with your Charcoal Rubbing Kit' },
    'the-chalk-line-at-the-old-boundary': { index:1, item:'charcoalRubbingKit', label:'Rub the county stone’s carved survey mark before the rain erases it' },
  };
  const inspectIds = ['measure', 'compare', 'ask'] as const;
  const toolUse = specialistUse[c.id];
  const inspectChoices: Scene['choices'] = c.inspect.map((label, i) => ({ id: inspectIds[i], label, next: 'test', effects: { setFlags: [`${c.id}_${inspectIds[i]}`] } }));
  if (toolUse) inspectChoices.push({ id:'specialistTool', label:toolUse.label, next:'test', requirements:{items:[toolUse.item]}, effects:{setFlags:[`${c.id}_specialistTool`]} });
  const actionChoices = [
    { id:'careful', label:c.actions[0], next:'settlement', effects:{ setFlags:[`${c.id}_careful`] } },
    { id:'verify', label:c.actions[1], next:'settlement', effects:{ setFlags:[`${c.id}_verified`] } },
    { id:'accuse', label:c.actions[2], next:'settlement', effects:{ setFlags:[`${c.id}_accused`] } },
  ];
  const settlementChoices: Scene['choices'] = [
    { id:'wage', label:`Accept the ${c.coins}-coin inspection fee`, next:'paid', effects:{ money:c.coins } },
    { id:'recordLesson', label:'Decline payment and keep the practical lesson', next:'lesson', effects:{ knowledge:[c.lesson] } },
    ...(item && itemName ? [{ id:'tool', label:`Accept the ${itemName} as compensation`, next:'gear', requirements:{ notOwnedItems:[item] }, effects:gearGain(item,provenance!,`earned_${item}_${c.id}`) }] : []),
  ];
  const scenes: Record<string, Scene> = {
    observe:s('observe','A Claim and a Physical Trace',`${c.scene} ${c.claim} You are asked to help assess the evidence, not to act as an officer.`,inspectChoices),
    test:s('test',c.testTitle,c.test,[...actionChoices]),
    settlement:{...s('settlement','What the Evidence Can Support',`${c.interpretation} The owner asks how you want to close the paid inspection.`,settlementChoices),textVariants:[
      { requirements:{flags:[`${c.id}_careful`]}, text:`${c.interpretation} ${c.careful}` },
      { requirements:{flags:[`${c.id}_verified`]}, text:`${c.interpretation} You preserve or verify the evidence before leaving; no unsupported identity is recorded.` },
      { requirements:{flags:[`${c.id}_accused`]}, text:`${c.interpretation} ${c.accuse}` },
    ]},
    paid:e('paid','A Limited Finding',`You accept ${c.coins} coins for the practical inspection. ${c.lesson}`),
    lesson:e('lesson','A Reusable Method',`You leave the fee and retain the method: ${c.lesson}`),
    ...(item && itemName ? { gear:e('gear','A Tool for Careful Records',`${provenance} The ${itemName} helps with ${itemSource}; it preserves a comparison, not a conclusion.`) } : {}),
  };
  if (c.combat) {
    scenes.test = s('test',c.testTitle,`${c.test} Before the owner can decide what to do, a person comes back to remove the disputed item and shoves the clerk aside. They have not drawn a weapon; the office door and public street are both clear.`,[
      { id:'callWitness',label:'Call the street watch and keep the clerk behind the counter',next:'settlement',effects:{setFlags:[`${c.id}_careful`]} },
      { id:'secureEvidence',label:'Move the evidence to the locked public office and withdraw',next:'settlement',effects:{setFlags:[`${c.id}_verified`]} },
      { id:'standGround',label:'Restrain the returning intruder',chance:{probability:.55,successNext:'settlement',failureNext:'settlement',successMessage:'The intruder backs away when the watch answers.',failureMessage:'You are struck in the struggle, but the intruder flees when the street watch arrives.',failureEffects:{health:-3,setFlags:[`${c.id}_verified`]},successEffects:{setFlags:[`${c.id}_careful`]} } },
    ]);
  }
  const tags = largeTags({ hook:`${c.claim} ${c.interpretation}`, role:'traveler/passenger', activity:'investigation/mystery', tone:c.risk === 'LOW' ? 'adventurous' : c.risk === 'HIGH' ? 'tense/dangerous' : 'tense', risk:c.risk, setting:c.setting, fantasy:'NONE', combat:c.combat ? 'POSSIBLE' : 'NONE', structures:['evidence review','multiple explanations','choice changes response','interpretation with uncertainty'], entry:['hired/posted work','accidental encounter'], rewards:['Knowledge','coins',...(item ? ['Gear'] : [])], outcomes:['success/partial success','walk-away/refusal'] });
  return largeAdventure(c.id,c.title,c.subtitle,tags,'observe',scenes);
}

export const INVESTIGATION_EVIDENCE_GENRE_BATCH: Scenario[] = stories.slice(0, 24).map(build);

export const INVESTIGATION_EVIDENCE_EDITORIAL_DRAFT_COUNT = stories.length;
